// Second review of the workbook view: what is being typed in the field of a note or in a tab
// is part of what is saved, and is not dropped by undo; a drag does not outlive the sheet it
// began on; a refusal that is said stays said; the sheet that was asked for is the one a saved
// file opens on. Every workbook is generated by code.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const HEADER_WIDTH = 72;
const COLUMN_WIDTH = 64;

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;

/** "One": A1 = 1. "Two": A1 = 2. "Three": nothing. */
const workbook = () =>
  buildXlsx({
    sheets: [
      { name: 'One', xml: worksheetXml(`<sheetData><row r="1">${num('A1', 1)}</row></sheetData>`) },
      { name: 'Two', xml: worksheetXml(`<sheetData><row r="1">${num('A1', 2)}</row></sheetData>`) },
      { name: 'Three', xml: worksheetXml('<sheetData/>') },
    ],
  });

const noteField = (page: Page) => page.locator('.bym-note-input');
const nameField = (page: Page) => page.locator('.bym-tabs input.bym-tab-input');
const live = (page: Page) => page.locator('.bym-view [aria-live]');

/** BymOffice.mount() in the page, with what onSave is given kept in window.__saved. */
async function mountPage(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/mount.html');
  await page.evaluate(
    async ([input, options]) => {
      const w = window as any;
      w.__saved = [];
      w.__notices = [];
      w.__keys = [];
      // After the handler of mount(): what became of the key.
      window.addEventListener('keydown', (event) => w.__keys.push({ key: event.key, prevented: event.defaultPrevented }));
      w.__mounted = await w.BymOffice.mount(document.getElementById('editor'), {
        file: new Uint8Array(input as number[]),
        locale: 'en-US',
        onSave: (bytes: Uint8Array) => w.__saved.push(Array.from(bytes)),
        onNotice: (notice: any) => w.__notices.push({ message: notice.message, kind: notice.kind }),
        ...(options as object),
      });
    },
    [Array.from(bytes), options] as [number[], Record<string, unknown>],
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

async function mountView(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/view.html');
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(([input, options]) => (window as any).__mountView(new Uint8Array(input as number[]), options), [Array.from(bytes), { locale: 'en-US', ...options }] as [number[], Record<string, unknown>]);
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

const mounted = <T>(page: Page, run: string): Promise<T> => page.evaluate(`(async () => { const mounted = window.__mounted; const view = mounted.view; return ${run}; })()`) as Promise<T>;
const view = <T>(page: Page, run: string): Promise<T> => page.evaluate(`(() => { const view = window.__view; return ${run}; })()`) as Promise<T>;

interface Read {
  names: string[];
  active: number;
  notes: string[];
  a1: unknown;
}

/** What a file says, read anew: the names of its sheets, the sheet it opens on, the notes and A1 of its first sheet. */
function read(page: Page, bytes: number[]): Promise<Read> {
  return page.evaluate(async (input) => {
    const api = (window as any).BymOffice;
    const book = await (await api.open(new Uint8Array(input))).workbook();
    const first = api.getCell(book.sheets[0], 0, 0);
    return {
      names: book.sheets.map((sheet: any) => sheet.name),
      active: book.activeSheet,
      notes: (book.sheets[0].comments || []).map((item: any) => `${api.cellName(item.row, item.col)}: ${item.text}`).sort(),
      a1: first ? first.value : null,
    };
  }, bytes);
}

const saveBytes = (page: Page): Promise<number[]> => mounted(page, 'Array.from(await mounted.save())');

test.describe('saving while a note or the name of a sheet is typed', () => {
  test('mount().save() takes the note that is being typed into the file and closes its field', async ({ page }) => {
    await mountPage(page, await workbook());
    expect(await mounted(page, 'view.editComment(1, 1)')).toBe(true);
    await noteField(page).fill('typed and not left');
    const saved = await read(page, await saveBytes(page));
    expect(saved.notes).toEqual(['B2: typed and not left']);
    await expect(noteField(page)).toHaveCount(0);
    expect(await mounted(page, 'view.isEditingComment')).toBe(false);
  });

  test('mount().save() takes the name that is being typed into the file and closes its field', async ({ page }) => {
    await mountPage(page, await workbook());
    expect(await mounted(page, 'view.startRename(1)')).toBe(true);
    await nameField(page).fill('Renamed');
    const saved = await read(page, await saveBytes(page));
    expect(saved.names).toEqual(['One', 'Renamed', 'Three']);
    await expect(nameField(page)).toHaveCount(0);
    expect(await mounted(page, 'view.isRenaming')).toBe(false);
  });

  test('a name that cannot be taken stays in its field, is said, and nothing is saved; once it can be taken the file has it', async ({ page }) => {
    await mountPage(page, await workbook());
    await mounted(page, 'view.startRename(1)');
    await nameField(page).fill('One');
    const outcome = await mounted<string>(page, 'mounted.save().then(() => "saved", (error) => "refused: " + (error && error.message))');
    expect(outcome).toMatch(/^refused: /);
    await expect(nameField(page)).toHaveValue('One');
    await expect(nameField(page)).toHaveAttribute('aria-invalid', 'true');
    expect(await mounted(page, 'view.workbook.sheets.map((sheet) => sheet.name)')).toEqual(['One', 'Two', 'Three']);
    const notices = await page.evaluate(() => (window as any).__notices);
    expect(notices.length).toBe(1);
    expect(notices[0].kind).toBe('error');
    await expect(live(page)).toHaveText(notices[0].message);
    // commitPending() says the same without throwing.
    expect(await mounted(page, 'view.commitPending()')).toBe(false);
    await nameField(page).fill('Second');
    expect(await mounted(page, 'view.commitPending()')).toBe(true);
    expect((await read(page, await saveBytes(page))).names).toEqual(['One', 'Second', 'Three']);
  });

  test('Ctrl+S in the field of a note saves through the application, with the note, and is not left to the browser', async ({ page }) => {
    await mountPage(page, await workbook());
    await mounted(page, 'view.editComment(2, 0)');
    await noteField(page).fill('saved by a key');
    await expect(noteField(page)).toBeFocused();
    await page.keyboard.press('Control+s');
    await expect.poll(() => page.evaluate(() => (window as any).__saved.length)).toBe(1);
    const saved = await read(page, await page.evaluate(() => (window as any).__saved[0]));
    expect(saved.notes).toEqual(['A3: saved by a key']);
    const keys = await page.evaluate(() => (window as any).__keys.filter((entry: any) => entry.key === 's' || entry.key === 'S'));
    expect(keys).toEqual([{ key: keys[0].key, prevented: true }]);
    await expect(noteField(page)).toHaveCount(0);
  });

  test('Ctrl+S in a tab saves through the application, with the name, and is not left to the browser', async ({ page }) => {
    await mountPage(page, await workbook());
    await mounted(page, 'view.startRename(2)');
    await nameField(page).fill('Third');
    await expect(nameField(page)).toBeFocused();
    await page.keyboard.press('Control+s');
    await expect.poll(() => page.evaluate(() => (window as any).__saved.length)).toBe(1);
    const saved = await read(page, await page.evaluate(() => (window as any).__saved[0]));
    expect(saved.names).toEqual(['One', 'Two', 'Third']);
    const keys = await page.evaluate(() => (window as any).__keys.filter((entry: any) => entry.key === 's' || entry.key === 'S'));
    expect(keys.map((entry: any) => entry.prevented)).toEqual([true]);
    await expect(nameField(page)).toHaveCount(0);
  });

  test('the bridge saves the note that is being typed', async ({ page }) => {
    await page.addInitScript(() => {
      (window as any).__messages = [];
      (window as any).BymOfficeHost = { postMessage: (json: unknown) => (window as any).__messages.push(json) };
    });
    await page.goto('/dist/bymoffice.webview.html');
    const send = (message: unknown) => page.evaluate((json) => (window as any).BymOfficeBridge.receive(json), JSON.stringify(message));
    const messages = (type: string) => page.evaluate((type) => ((window as any).__messages as string[]).map((entry) => JSON.parse(entry)).filter((message) => message.type === type), type);
    await send({ type: 'load', id: 'l', data: Buffer.from(await workbook()).toString('base64') });
    await expect.poll(async () => (await messages('loaded')).length).toBe(1);
    const input = page.locator('.bym-input');
    await input.focus();
    await expect(input).toBeFocused();
    await page.keyboard.press('Shift+F2');
    await expect(noteField(page)).toBeFocused();
    await noteField(page).fill('over the bridge');
    await send({ type: 'save', id: 's' });
    await expect.poll(async () => (await messages('saved')).length).toBe(1);
    const data = (await messages('saved'))[0].data as string;
    const saved = await read(page, Array.from(Buffer.from(data, 'base64')));
    expect(saved.notes).toEqual(['A1: over the bridge']);
    await expect(noteField(page)).toHaveCount(0);
  });
});

test.describe('undo while a note or the name of a sheet is typed', () => {
  test('undo() applies the note that is being typed and undoes nothing else; the next call undoes it', async ({ page }) => {
    await mountView(page, await workbook());
    await view(page, 'view.setCellInput(0, 0, "first")');
    expect(await view(page, 'view.editComment(1, 1)')).toBe(true);
    await noteField(page).fill('kept');
    expect(await view(page, 'view.undo()')).toBe(true);
    await expect(noteField(page)).toHaveCount(0);
    const state = () => view<[unknown, string[]]>(page, '[BymOffice.getCell(view.workbook.sheets[0], 0, 0).value, (view.workbook.sheets[0].comments || []).map((item) => item.text)]');
    expect(await state()).toEqual(['first', ['kept']]);
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await state()).toEqual(['first', []]);
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await state()).toEqual([1, []]);
    // Redo is no different: what is typed is applied, and nothing is done again in that call.
    await view(page, 'view.editComment(2, 2)');
    await noteField(page).fill('again');
    expect(await view(page, 'view.redo()')).toBe(true);
    expect(await state()).toEqual([1, ['again']]);
  });

  test('undo() applies the name that is being typed; a name that cannot be taken stays in its field', async ({ page }) => {
    await mountView(page, await workbook());
    const names = () => view<string[]>(page, 'view.workbook.sheets.map((sheet) => sheet.name)');
    await view(page, 'view.startRename(1)');
    await nameField(page).fill('Second');
    expect(await view(page, 'view.undo()')).toBe(true);
    await expect(nameField(page)).toHaveCount(0);
    expect(await names()).toEqual(['One', 'Second', 'Three']);
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await names()).toEqual(['One', 'Two', 'Three']);

    await view(page, 'view.startRename(1)');
    await nameField(page).fill('one');
    expect(await view(page, 'view.undo()')).toBe(false);
    await expect(nameField(page)).toHaveValue('one');
    expect(await names()).toEqual(['One', 'Two', 'Three']);
    expect(await view(page, 'view.history.canRedo')).toBe(true);
  });

  test('the toolbar does not offer undo and redo while a note or a name is typed', async ({ page }) => {
    await page.goto('/e2e/pages/editor.html');
    await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
    await page.evaluate((input) => (window as any).__mountEditor(new Uint8Array(input), { locale: 'en-US' }), Array.from(await workbook()));
    await expect(page.locator('#host .bym-canvas')).toBeVisible();
    const editor = <T>(run: string): Promise<T> => page.evaluate(`(() => { const view = window.__editor.view; return ${run}; })()`) as Promise<T>;
    const undo = page.locator('#host [data-command="undo"]');
    await editor('view.setCellInput(0, 0, "first")');
    await expect(undo).toBeEnabled();
    await editor('view.editComment(1, 1)');
    await expect(noteField(page)).toBeFocused();
    await expect(undo).toBeDisabled();
    await page.keyboard.press('Escape');
    await expect(noteField(page)).toHaveCount(0);
    await expect(undo).toBeEnabled();
    await editor('view.startRename(1)');
    await expect(nameField(page)).toBeFocused();
    await expect(undo).toBeDisabled();
    await page.keyboard.press('Escape');
    await expect(nameField(page)).toHaveCount(0);
    await expect(undo).toBeEnabled();
  });
});

/** A pointer event on the canvas at a point of the canvas. */
function pointer(page: Page, type: string, x: number, y: number, kind: 'touch' | 'mouse', id = 77): Promise<void> {
  return page.evaluate(
    ([type, x, y, kind, id]) => {
      const canvas = document.querySelector('.bym-canvas')!;
      const box = canvas.getBoundingClientRect();
      const init = { pointerId: id as number, pointerType: kind as string, isPrimary: true, clientX: box.left + (x as number), clientY: box.top + (y as number), button: 0, buttons: type === 'pointerup' ? 0 : 1, bubbles: true, cancelable: true };
      canvas.dispatchEvent(new PointerEvent(type as string, init));
    },
    [type, x, y, kind, id] as [string, number, number, string, number],
  );
}

/** The widths the sheets state for their columns: none in the workbook of these tests until a border is dragged. */
const columns = (page: Page) => view<number[]>(page, 'view.workbook.sheets.map((sheet) => sheet.columns.length)');

test.describe('drags and the sheet they are made on', () => {
  test('a finger on a border resizes the column of the sheet that is shown, also when what is typed belongs to another', async ({ page }) => {
    await mountView(page, await workbook());
    const input = page.locator('.bym-input');
    await input.focus();
    await expect(input).toBeFocused();
    // A formula is begun on One, and Two is shown for it to point at...
    await page.keyboard.type('=');
    await page.locator('.bym-tabs button', { hasText: 'Two' }).click();
    expect(await view(page, '[view.activeSheet, view.isEditing]')).toEqual([1, true]);
    await expect(input).toBeFocused();
    // ...and then the text is no formula any more.
    await page.keyboard.press('Backspace');
    await page.keyboard.type('7');
    expect(await view(page, '[view.activeSheet, view.isEditing, view.editText]')).toEqual([1, true, '7']);
    const border = HEADER_WIDTH + COLUMN_WIDTH;
    await pointer(page, 'pointerdown', border, 10, 'touch');
    await pointer(page, 'pointermove', border + 30, 10, 'touch');
    await pointer(page, 'pointermove', border + 40, 10, 'touch');
    await pointer(page, 'pointerup', border + 40, 10, 'touch');
    expect(await view(page, 'view.isEditing')).toBe(false);
    // What was typed is in its cell, on its sheet; the column that grew is one of the sheet under the finger.
    expect(await view(page, 'BymOffice.getCell(view.workbook.sheets[0], 0, 0).value')).toBe(7);
    expect(await view(page, 'view.activeSheet')).toBe(1);
    expect(await columns(page)).toEqual([0, 1, 0]);
  });

  test('undoing an operation on the sheets ends a drag that was begun before it', async ({ page }) => {
    await mountView(page, await workbook());
    await view(page, 'view.insertSheet(0, "New")');
    expect(await view(page, 'view.activeSheet')).toBe(0);
    const border = HEADER_WIDTH + COLUMN_WIDTH;
    await pointer(page, 'pointerdown', border, 10, 'mouse');
    await pointer(page, 'pointermove', border + 20, 10, 'mouse');
    // The sheet the border belongs to goes away under the drag.
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await view(page, 'view.workbook.sheets.map((sheet) => sheet.name)')).toEqual(['One', 'Two', 'Three']);
    await pointer(page, 'pointermove', border + 40, 10, 'mouse');
    await pointer(page, 'pointerup', border + 40, 10, 'mouse');
    expect(await columns(page)).toEqual([0, 0, 0]);
    expect(await view(page, 'view.history.canUndo')).toBe(false);
  });
});

test.describe('what is said and what is kept', () => {
  test('a name that is refused when its field is left stays said, whatever the press that left it says', async ({ page }) => {
    await mountView(page, await workbook());
    await view(page, 'view.startRename(1)');
    await nameField(page).fill('One');
    // A press on a cell: the field is left, and the cell is selected and read out.
    await page.locator('.bym-canvas').click({ position: { x: HEADER_WIDTH + COLUMN_WIDTH + 20, y: 22 + 50 } });
    await expect(nameField(page)).toHaveCount(0);
    await expect.poll(() => page.evaluate(() => (window as any).__notices.length)).toBe(1);
    const notice = await page.evaluate(() => (window as any).__notices[0]);
    expect(notice.kind).toBe('error');
    await expect(live(page)).toHaveText(notice.message);
    expect(await view(page, 'view.workbook.sheets[1].name')).toBe('Two');

    // The same when another sheet is shown by a call.
    await view(page, 'view.startRename(1)');
    await nameField(page).fill('Three');
    await view(page, 'view.setActiveSheet(0)');
    await expect.poll(() => page.evaluate(() => (window as any).__notices.length)).toBe(2);
    await expect(live(page)).toHaveText(await page.evaluate(() => (window as any).__notices[1].message));
  });

  test('a view opened on a sheet that was asked for saves a file that opens on it; without the option nothing is written', async ({ page }) => {
    const bytes = await workbook();
    await mountPage(page, bytes, { sheet: 2 });
    expect(await mounted(page, 'view.activeSheet')).toBe(2);
    await mounted(page, 'view.setColumnWidth(0, 0, 120)');
    const saved = await read(page, await saveBytes(page));
    expect(saved.active).toBe(2);

    await mountPage(page, bytes);
    expect(await saveBytes(page)).toEqual(Array.from(bytes));
    // Asked for and nothing changed: the file as it was, whatever sheet is shown.
    await mountPage(page, bytes, { sheet: 1 });
    expect(await saveBytes(page)).toEqual(Array.from(bytes));
  });

  test('an input method composing in a tab or in the field of a note is none of the grid', async ({ page }) => {
    await mountView(page, await workbook());
    await page.evaluate(() => {
      const w = window as any;
      w.__compositions = 0;
      const root = document.querySelector('.bym-view')!;
      root.addEventListener('compositionstart', () => w.__compositions++);
      root.addEventListener('compositionend', () => w.__compositions++);
    });
    const compose = (selector: string) =>
      page.evaluate((selector) => {
        const field = document.querySelector(selector)!;
        field.dispatchEvent(new CompositionEvent('compositionstart', { bubbles: true, data: '' }));
      }, selector);
    await view(page, 'view.startRename(1)');
    await compose('.bym-tabs input.bym-tab-input');
    // Taken away in the middle of the composition: its end is never reported.
    await view(page, 'view.setActiveSheet(0)');
    await expect(nameField(page)).toHaveCount(0);
    await view(page, 'view.editComment(1, 1)');
    await compose('.bym-note-input');
    await view(page, 'view.cancelEditing(), view.setActiveSheet(2), view.setActiveSheet(0)');
    expect(await page.evaluate(() => (window as any).__compositions)).toBe(0);
    // A formula typed afterwards takes a reference from a press: nothing thinks an input method is still composing.
    const input = page.locator('.bym-input');
    await input.focus();
    await page.keyboard.type('=');
    await pointer(page, 'pointerdown', HEADER_WIDTH + COLUMN_WIDTH + 20, 22 + 50, 'mouse');
    await pointer(page, 'pointerup', HEADER_WIDTH + COLUMN_WIDTH + 20, 22 + 50, 'mouse');
    expect(await view(page, 'view.editText')).toBe('=B3');
  });
});
